class RunReport(pydantic.BaseModel):
    """The result of a single test-function execution."""
    model_config = pydantic.ConfigDict(
        arbitrary_types_allowed=True,
        extra="ignore",
        populate_by_name=True,
    )
    outcome: Outcome
    duration_ms: int
    message: typing.Optional[str] = None


class TestReport(pydantic.BaseModel):
    """The aggregated result of all runs for a single `test` block."""
    model_config = pydantic.ConfigDict(
        arbitrary_types_allowed=True,
        extra="ignore",
        populate_by_name=True,
    )
    outcome: Outcome
    runs: typing.List[RunReport]


class TestSetReport(pydantic.BaseModel):
    """The aggregated result of all tests in a `testset` block."""
    model_config = pydantic.ConfigDict(
        arbitrary_types_allowed=True,
        extra="ignore",
        populate_by_name=True,
    )
    outcome: Outcome
    passed: int
    failed: int
    total: int
    failed_names: typing.List[str]
    results: typing.List[ChildReport]
    result_names: typing.Optional[typing.List[str]] = None


class _NamedChildReport(pydantic.BaseModel):
    """(internal) A named child report used internally when aggregating testset children."""
    model_config = pydantic.ConfigDict(
        arbitrary_types_allowed=True,
        extra="ignore",
        populate_by_name=True,
    )
    name: str
    report: ChildReport


class TestSetChild(pydantic.BaseModel):
    """A named child of a testset. Runners decide when, and whether, to invoke it."""
    model_config = pydantic.ConfigDict(
        arbitrary_types_allowed=True,
        extra="ignore",
        populate_by_name=True,
    )
    name: str
    run: ChildReportThunk
    is_container: bool


class FlatTestReport(pydantic.BaseModel):
    """
    Aggregated, already-flattened report returned to the CLI driver.

    `outcome` is the aggregate verdict (honors testset runners). Counts are
    leaf-level: `failed` = hard failures, `tolerated` = failing leaves whose
    enclosing testset runner still passed (e.g. under `PassRate`), `passed` and
    `total` as usual. `failed_names` are the hard-failure names; `messages` are
    every failing run's message. The three name arrays partition selected leaf
    IDs by their actual outcome after applying testset-runner tolerance.

    Attributes:
        outcome
        passed
        failed
        tolerated
        total
        passed_names
        failed_names
        tolerated_names
        passed_ms: Per-leaf durations, parallel to the matching name array, when the
            executed child partition supplied them; EMPTY when the identities came
            from fallback selection/failure correlation (durations unknown there).
            `-1` marks an individual leaf with no measured run (an expansion
            failure sentinel). Consumers must treat a shorter-than-names array as
            "no duration for the tail", never index blindly.
        failed_ms
        tolerated_ms
        messages
    """
    model_config = pydantic.ConfigDict(
        arbitrary_types_allowed=True,
        extra="ignore",
        populate_by_name=True,
    )
    outcome: Outcome
    passed: int
    failed: int
    tolerated: int
    total: int
    passed_names: typing.List[str]
    failed_names: typing.List[str]
    tolerated_names: typing.List[str]
    passed_ms: typing.List[int]
    failed_ms: typing.List[int]
    tolerated_ms: typing.List[int]
    messages: typing.List[str]


SerializedTestDef: typing.TypeAlias = typing.Union[SerializedTest, SerializedTestSet]


ChildReport: typing.TypeAlias = typing.Union[TestReport, TestSetReport]


TestSetBody: typing.TypeAlias = typing.Callable[[TestCollector], None]


TestReportThunk: typing.TypeAlias = typing.Callable[[], TestReport]


TestSetReportThunk: typing.TypeAlias = typing.Callable[[], TestSetReport]


ChildReportThunk: typing.TypeAlias = typing.Callable[[], ChildReport]


TestRunner: typing.TypeAlias = typing.Callable[[TestReportThunk], TestReportThunk]


TestSetRunner: typing.TypeAlias = typing.Callable[[typing.List[TestSetChild]], TestSetReport]


